```
sort meetings by start time
free = min-heap of room numbers 0..n-1
busy = min-heap of (endTime, room)
for each meeting (s, e):
    while busy not empty and busy.top.endTime <= s:
        free.push(busy.top.room); busy.pop()
    if free not empty:
        r = free.pop(); count[r]++; busy.push(e, r)
    else:
        (t, r) = busy.pop(); count[r]++; busy.push(t + (e-s), r)
return room with max count (lowest on tie)
```

code.cpp:
class Solution {
public:
    int mostBooked(int n, vector<vector<int>>& meetings) {
        sort(meetings.begin(), meetings.end());

        vector<int> count(n, 0);

        priority_queue<int, vector<int>, greater<int>> freeRooms;
        for (int i = 0; i < n; i++) freeRooms.push(i);

        priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> busy;

        for (auto& m : meetings) {
            long long start = m[0], end = m[1];

            while (!busy.empty() && busy.top().first <= start) {
                freeRooms.push(busy.top().second);
                busy.pop();
            }

            if (!freeRooms.empty()) {
                int room = freeRooms.top();
                freeRooms.pop();
                count[room]++;
                busy.push({end, room});
            } else {
                auto [endTime, room] = busy.top();
                busy.pop();
                count[room]++;
                busy.push({endTime + (end - start), room});
            }
        }

        int bestRoom = 0;
        for (int i = 1; i < n; i++) {
            if (count[i] > count[bestRoom]) bestRoom = i;
        }
        return bestRoom;
    }
};
